public static void main(String[] args) {
	Scanner scan = new Scanner(System.in);
	int n = scan.nextInt();
	int maxSize = 1;
	for (int i = 0; i < n; i++) {
		maxSize *= 3;
	}
	// System.out.println(maxSize); // Removed unnecessary debug print
	char[][] result = new char[1][1];
	result[0][0] = '#';
	int size = 3;
	while (size <= maxSize) {
		char[][] array = result;
		// System.out.println(array.length); // Removed unnecessary debug print
		result = new char[size][size];
		for (int j = 0; j < array.length; j++) {
			for (int i = 0; i < array.length; i++) {
				extendCarpet(i, j, result, array[i][j]);
			}
		}
		size *= 3;
	}

	for (int j = 0; j < result.length; j++) {
		for (int i = 0; i < result.length; i++) {
			System.out.print(result[j][i]); // Corrected the output to print in the correct order
		}
		System.out.println();
	}

	scan.close();
}

